<script lang="ts">
import { defineComponent } from 'vue';
import { useDocNetAgentStore } from 'src/store/DocNet/docnet-agents.store';
import { useDocNetIssueStore } from 'src/store/DocNet/docnet-issues.store';
import { useDocNetInboxStore } from 'src/store/DocNet/docnet-inbox.store';
import { useDocNetEmailStore } from 'src/store/DocNet/docnet-email.store';
import { useDocNetSettingsStore } from 'src/store/DocNet/docnet-settings.store';
import { storeToRefs } from 'pinia';

export default defineComponent({
  name: 'DocNetSidebar',

  setup() {
    const agentStore = useDocNetAgentStore();
    const issueStore = useDocNetIssueStore();
    const inboxStore = useDocNetInboxStore();
    const emailStore = useDocNetEmailStore();

    const { profiles } = storeToRefs(agentStore);
    const { activeIssueCount } = storeToRefs(issueStore);
    const { pendingCount } = storeToRefs(inboxStore);
    const { unreadCount } = storeToRefs(emailStore);

    const settingsStore = useDocNetSettingsStore();
    const { useMockData } = storeToRefs(settingsStore);

    return {
      agents: profiles,
      activeIssueCount,
      pendingCount,
      unreadEmailCount: unreadCount,
      useMockData,
      settingsStore,
    };
  },

  data() {
    return {
      agentsExpanded: false,
    };
  },

  mounted() {
    // Auto-expand agents section if currently on an agent page
    if (this.$route.path.startsWith('/doc-net/agents')) {
      this.agentsExpanded = true;
    }
  },

  computed: {
    routerAgents() {
      return this.agents.filter((a) => a.role === 'router' && a.agent.is_enabled !== false);
    },
    orchestratorAgents() {
      return this.agents.filter((a) => a.role === 'orchestrator' && a.agent.is_enabled !== false);
    },
    specialistAgents() {
      return this.agents.filter((a) => a.role !== 'router' && a.role !== 'orchestrator' && a.agent.is_enabled !== false);
    },
  },

  methods: {
    isExactRoute(path: string): boolean {
      return this.$route.path === path;
    },
    isRouteActive(path: string): boolean {
      return this.$route.path === path || this.$route.path.startsWith(path + '/');
    },
  },
});
</script>

