<template>
  <SubHeader
    name="doc_net"
    :label="$t('doc_net')"
    :onSearch="false"
  />

  <!-- Subscription gate -->
  <div v-if="!hasDocNetAccess" class="q-pa-xl text-center">
    <q-icon name="lock" size="64px" color="grey-5" style="opacity: 0.5" />
    <div class="text-h6 q-mt-md text-grey-7">{{ $t('ACTION_NOT_ALLOWED') }}</div>
    <div class="text-caption text-grey-5 q-mt-sm">{{ $t('sdk_requires_docnet_subscription') }}</div>
  </div>

  <div v-else class="docnet-layout">
    <!-- Mobile sidebar toggle -->
    <q-btn
      v-if="isMobileView"
      flat
      round
      dense
      icon="menu"
      class="sidebar-toggle"
      @click="sidebarOpen = true"
    />

    <!-- Mobile: sidebar as drawer -->
    <q-drawer
      v-if="isMobileView"
      v-model="sidebarOpen"
      bordered
      side="left"
      :width="260"
      :breakpoint="0"
      overlay
      behavior="mobile"
    >
      <DocNetSidebar @click="sidebarOpen = false" />
    </q-drawer>

    <!-- Desktop: sidebar always visible -->
    <div v-if="!isMobileView" class="docnet-sidebar-wrapper">
      <DocNetSidebar />
    </div>

    <!-- Content area -->
    <div class="docnet-content">
      <router-view />
    </div>
  </div>
</template>

<script lang="ts">
import { defineComponent } from 'vue';
import { storeToRefs } from 'pinia';
import SubHeader from 'src/pages/Settings/Components/Sub-Header.vue';
import DocNetSidebar from 'src/pages/DocNet/components/DocNetSidebar.vue';
import { useDocNetIssueStore } from 'src/store/DocNet/docnet-issues.store';
import { useDocNetEmailStore } from 'src/store/DocNet/docnet-email.store';
import { useDocNetInboxStore } from 'src/store/DocNet/docnet-inbox.store';
import { useSettingStore } from 'src/store/main';
import { hasDocNetAccess } from 'src/utils/UserDetails';

export default defineComponent({
  name: 'DocNetLayout',

  components: {
    SubHeader,
    DocNetSidebar,
  },

  setup() {
    // Stores are used by DocNetSidebar — data comes via WebSocket list_changed events
    useDocNetEmailStore();
    useDocNetIssueStore();
    useDocNetInboxStore();

    const settingsStore = useSettingStore();
    const { user_settings } = storeToRefs(settingsStore);

    return { user_settings };
  },

  data() {
    return {
      sidebarOpen: false,
      windowWidth: window.innerWidth,
      resizeTimer: null as ReturnType<typeof setTimeout> | null,
    };
  },

  computed: {
    hasDocNetAccess(): boolean {
      return hasDocNetAccess(this.user_settings);
    },
    isMobileView(): boolean {
      return this.windowWidth < 768;
    },
  },

  mounted() {
    window.addEventListener('resize', this.handleResize);
  },

  beforeUnmount() {
    window.removeEventListener('resize', this.handleResize);
    if (this.resizeTimer) clearTimeout(this.resizeTimer);
  },

  methods: {
    handleResize() {
      if (this.resizeTimer) clearTimeout(this.resizeTimer);
      this.resizeTimer = setTimeout(() => {
        this.windowWidth = window.innerWidth;
      }, 150);
    },
  },
});
</script>

